import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Bell, X, Clock, Calendar, MessageCircle, Check, CheckCircle2 } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { useLanguage } from '../../hooks/useLanguage';
import { Button } from '../ui/Button';
import { useDialogContext } from '../../contexts/DialogContext';
import api from '../../services/api';
import AppointmentDetailsModal from '../modals/AppointmentDetailsModal';

const SimpleNotificationCenter = ({ isOpen, onClose }) => {
  const { user } = useAuth();
  const { isRTL } = useLanguage();
  const dialog = useDialogContext();
  const navigate = useNavigate();
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(false);
  const [processingId, setProcessingId] = useState(null);
  const [selectedAppointment, setSelectedAppointment] = useState(null);
  const [showAppointmentModal, setShowAppointmentModal] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadNotifications();
    }
  }, [isOpen]);

  const loadNotifications = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/notifications?is_read=false');

      if (response.data && response.data.success) {
        // Afficher uniquement les notifications non lues
        setNotifications(response.data.notifications || []);
      }
    } catch (error) {
      console.error('Erreur chargement notifications:', error);
      setNotifications([]);
    } finally {
      setLoading(false);
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'absence_request':
        return <Calendar className="w-4 h-4 text-blue-500" />;
      case 'event_task':
        return <CheckCircle2 className="w-4 h-4 text-green-500" />;
      case 'event_memo':
        return <MessageCircle className="w-4 h-4 text-purple-500" />;
      case 'event_rdv':
      case 'event_medical':
      case 'event_meeting':
        return <Calendar className="w-4 h-4 text-orange-500" />;
      case 'event_status_changed':
        return <Check className="w-4 h-4 text-blue-500" />;
      case 'event_updated':
        return <Clock className="w-4 h-4 text-yellow-500" />;
      default:
        return <Bell className="w-4 h-4 text-gray-500" />;
    }
  };

  const markAsRead = async (notificationId, showToast = true) => {
    try {
      setProcessingId(notificationId);

      const response = await api.put(`/api/notifications/${notificationId}/read`);

      if (response.data.success) {
        // Retirer la notification de la liste (puisqu'elle est maintenant lue)
        setNotifications(prev =>
          prev.filter(notif => notif.id !== notificationId)
        );
        if (showToast) {
          dialog.success(isRTL ? 'تم تحديد الإشعار كمقروء' : 'Notification marquée comme lue');
        }
      }
    } catch (error) {
      console.error('Erreur marquage notification:', error);
      if (showToast) {
        dialog.error(isRTL ? 'خطأ في تحديث الإشعار' : 'Erreur lors de la mise à jour');
      }
    } finally {
      setProcessingId(null);
    }
  };

  const loadAppointmentDetails = async (appointmentId) => {
    try {
      console.log('📅 Chargement détails RDV:', appointmentId);
      const response = await api.get(`/api/appointments/${appointmentId}`);
      console.log('📅 Réponse API:', response.data);

      if (response.data.success && response.data.appointment) {
        console.log('✅ RDV chargé, ouverture modal');
        setSelectedAppointment(response.data.appointment);
        setShowAppointmentModal(true);
      } else {
        console.warn('⚠️ Pas de données RDV dans la réponse');
      }
    } catch (error) {
      console.error('❌ Erreur chargement détails RDV:', error);
      dialog.error(isRTL ? 'خطأ في تحميل تفاصيل الموعد' : 'Erreur lors du chargement des détails');
    }
  };

  const handleNotificationClick = async (notification) => {
    try {
      // Marquer comme lue SANS afficher le toast
      await markAsRead(notification.id, false);

      // Fermer le panneau de notifications
      onClose();

      // Déterminer la route selon le rôle de l'utilisateur
      const isParent = user?.role === 'parent';
      const messagesRoute = isParent ? '/mon-espace/messages' : '/dashboard/messages';
      const announcementsRoute = isParent ? '/mon-espace/announcements' : '/dashboard';
      const settingsRoute = '/dashboard/settings';

      // Rediriger selon le type de notification
      if (notification.type === 'staff_message') {
        // Notification de message - related_id contient l'ID de l'expéditeur
        if (notification.related_id) {
          // Ouvrir la conversation avec le contact (related_id = sender_id)
          navigate(`${messagesRoute}?contactId=${notification.related_id}`);
        } else {
          navigate(messagesRoute);
        }
      } else if (notification.type === 'announcement') {
        // Notification d'annonce - Parents vont à /mon-espace/announcements, Staff/Admin vont au dashboard
        navigate(announcementsRoute);
      } else if (notification.type === 'absence_request') {
        // Rediriger vers la page de gestion avec l'ID de la demande
        if (notification.related_id) {
          navigate(`/dashboard/absence-management?requestId=${notification.related_id}`);
        } else {
          navigate('/dashboard/absence-management');
        }
      } else if (notification.type && notification.type.startsWith('event_')) {
        // Toutes les notifications d'événements
        if (notification.related_id) {
          navigate(`/dashboard/events/${notification.related_id}`);
        } else {
          navigate('/dashboard/events/list');
        }
      } else if (notification.type === 'task' || notification.type === 'task_assigned') {
        // Notification de tâche
        if (notification.related_id) {
          navigate(`/dashboard/tasks?taskId=${notification.related_id}`);
        } else {
          navigate('/dashboard/tasks');
        }
      } else if (notification.type === 'appointment' || notification.type === 'appointment_proposed' || notification.type?.startsWith('appointment_')) {
        // Notification de rendez-vous - Charger les détails et ouvrir le modal
        console.log('🔔 Notification RDV cliquée:', notification);
        if (notification.related_id) {
          await loadAppointmentDetails(notification.related_id);
        } else {
          navigate('/dashboard/appointments');
        }
      } else if (notification.type === 'holiday_added' || notification.type === 'holiday_removed' ||
        notification.type === 'vacation_added' || notification.type === 'vacation_removed') {
        // Notifications jours fériés/vacances - Rediriger vers le dashboard/mon-espace (widget jours fériés visible)
        // Admin va aux paramètres, les autres vont au dashboard où le widget est affiché
        if (user?.role === 'admin' || user?.role === 'developer') {
          navigate(`${settingsRoute}?section=holidays`);
        } else {
          navigate(isParent ? '/mon-espace' : '/dashboard');
        }
      } else if (notification.type === 'schedule_changed' || notification.type === 'saturday_changed' || notification.type === 'phone_changed') {
        // Notifications paramètres crèche - Admin/Developer vers paramètres, autres vers dashboard
        if (user?.role === 'admin' || user?.role === 'developer') {
          navigate(settingsRoute);
        } else {
          navigate(isParent ? '/mon-espace' : '/dashboard');
        }
      } else if (notification.type === 'birthday_reminder') {
        // Anniversaire - Rediriger vers le dashboard
        navigate('/dashboard');
      } else if (notification.type === 'payment_alert') {
        // Alerte paiement - Parents vers mon-espace, Admin vers dashboard
        navigate(isParent ? '/mon-espace' : '/dashboard');
      } else if (notification.type === 'activity') {
        // Activité publiée - Parents vers activités
        navigate(isParent ? '/mon-espace/activities' : '/dashboard/activities');
      }
    } catch (error) {
      console.error('Erreur lors du clic sur la notification:', error);
    }
  };

  const acknowledgeAbsenceRequest = async (notificationId, absenceRequestId) => {
    try {
      setProcessingId(notificationId);

      const response = await api.put(`/api/absence-requests/${absenceRequestId}/acknowledge`, {
        admin_notes: 'Demande prise en compte par l\'administration'
      });

      if (response.data.success) {
        dialog.success(isRTL ? 'تم إرسال إشعار الاستلام' : 'Demande validée');

        // Supprimer la notification de la liste au lieu de la marquer comme lue
        setNotifications(prev => prev.filter(notif => notif.id !== notificationId));
      }
    } catch (error) {
      console.error('Erreur accusé de réception:', error);
      dialog.error(isRTL ? 'خطأ في إرسال إشعار الاستلام' : 'Erreur lors de la validation');
    } finally {
      setProcessingId(null);
    }
  };

  const markAllAsRead = async () => {
    try {
      const response = await api.put('/api/notifications/read-all');

      if (response.data.success) {
        setNotifications(prev =>
          prev.map(notif => ({ ...notif, is_read: true }))
        );
        dialog.success(isRTL ? 'تم تحديد جميع الإشعارات كمقروءة' : 'Toutes les notifications marquées comme lues');
      }
    } catch (error) {
      console.error('Erreur marquage toutes notifications:', error);
      dialog.error(isRTL ? 'خطأ في تحديث الإشعارات' : 'Erreur lors de la mise à jour');
    }
  };

  const formatDate = (dateString) => {
    try {
      const date = new Date(dateString);
      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMins / 60);
      const diffDays = Math.floor(diffHours / 24);

      if (diffMins < 1) return isRTL ? 'الآن' : 'Maintenant';
      if (diffMins < 60) return isRTL ? `منذ ${diffMins} دقيقة` : `Il y a ${diffMins} min`;
      if (diffHours < 24) return isRTL ? `منذ ${diffHours} ساعة` : `Il y a ${diffHours}h`;
      if (diffDays < 7) return isRTL ? `منذ ${diffDays} يوم` : `Il y a ${diffDays}j`;

      return date.toLocaleDateString(isRTL ? 'ar-TN' : 'fr-FR');
    } catch {
      return dateString;
    }
  };

  return (
    <>
      {/* Modal détails rendez-vous - TOUJOURS rendu pour rester visible après fermeture notifications */}
      <AppointmentDetailsModal
        isOpen={showAppointmentModal}
        onClose={() => {
          setShowAppointmentModal(false);
          setSelectedAppointment(null);
        }}
        appointment={selectedAppointment}
        onSuccess={() => {
          setShowAppointmentModal(false);
          setSelectedAppointment(null);
          loadNotifications(); // Recharger les notifications
        }}
      />

      {!isOpen && null}
      {isOpen && (
        <AnimatePresence>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-start justify-end p-4"
            onClick={onClose}
          >
            <motion.div
              initial={{ x: 400, opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: 400, opacity: 0 }}
              className={`bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md max-h-[90vh] overflow-hidden ${isRTL ? 'rtl' : 'ltr'}`}
              onClick={(e) => e.stopPropagation()}
            >
              {/* En-tête */}
              <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
                <div className="flex items-center">
                  <Bell className="w-5 h-5 mr-2 rtl:mr-0 rtl:ml-2 text-gray-600 dark:text-gray-400" />
                  <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                    {isRTL ? 'الإشعارات' : 'Notifications'}
                  </h2>
                  {notifications.filter(n => !n.is_read).length > 0 && (
                    <span className="ml-2 rtl:ml-0 rtl:mr-2 px-2 py-1 text-xs bg-red-500 text-white rounded-full">
                      {notifications.filter(n => !n.is_read).length}
                    </span>
                  )}
                </div>
                <div className="flex items-center space-x-2 rtl:space-x-reverse">
                  <button
                    onClick={onClose}
                    className="p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>
              </div>

              {/* Contenu */}
              <div className="overflow-y-auto max-h-[calc(90vh-80px)]">
                {loading ? (
                  <div className="flex justify-center items-center py-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
                  </div>
                ) : notifications.length === 0 ? (
                  <div className="text-center py-8">
                    <Bell className="w-12 h-12 mx-auto text-gray-400 mb-4" />
                    <p className="text-gray-500">
                      {isRTL ? 'لا توجد إشعارات' : 'Aucune notification'}
                    </p>
                  </div>
                ) : (
                  <div className="divide-y divide-gray-200 dark:divide-gray-700">
                    {notifications.map((notification) => {
                      const isAbsenceRequest = notification.type === 'absence_request' && notification.related_id;

                      return (
                        <div
                          key={notification.id}
                          className={`p-4 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors cursor-pointer ${!notification.is_read ? 'bg-blue-50 dark:bg-blue-900/10' : ''
                            }`}
                          onClick={() => handleNotificationClick(notification)}
                        >
                          <div className="flex items-start space-x-3 rtl:space-x-reverse">
                            <div className="flex-shrink-0">
                              {getNotificationIcon(notification.type)}
                            </div>

                            <div className="flex-1 min-w-0">
                              <div className="flex items-center justify-between">
                                <h3 className="text-sm font-medium text-gray-900 dark:text-white">
                                  {notification.title}
                                </h3>
                                <div className="flex items-center space-x-1 rtl:space-x-reverse">
                                  {!notification.is_read && (
                                    <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                                  )}
                                  <span className="text-xs text-gray-500">
                                    {formatDate(notification.created_at)}
                                  </span>
                                </div>
                              </div>

                              <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                                {notification.message}
                              </p>

                              {/* Actions pour les demandes d'absence */}
                              {isAbsenceRequest && (user?.role === 'admin' || user?.role === 'staff' || user?.role === 'developer') && (
                                <div className="mt-3" onClick={(e) => e.stopPropagation()}>
                                  <Button
                                    size="sm"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      acknowledgeAbsenceRequest(notification.id, notification.related_id);
                                    }}
                                    disabled={processingId === notification.id}
                                    className="text-xs"
                                  >
                                    {processingId === notification.id ? (
                                      <div className="animate-spin rounded-full h-3 w-3 border-b-2 border-white mr-1 rtl:mr-0 rtl:ml-1"></div>
                                    ) : (
                                      <CheckCircle2 className="w-3 h-3 mr-1 rtl:mr-0 rtl:ml-1" />
                                    )}
                                    {isRTL ? 'تأكيد الاستلام' : 'Valider'}
                                  </Button>
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        </AnimatePresence>
      )}
    </>
  );
};

export default SimpleNotificationCenter;
