import { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Menu, Bell, User, LogOut, Settings, ChevronDown, Home } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { useLanguage } from '../../hooks/useLanguage';
import { useNotifications } from '../../hooks/useNotifications';
import { useProfileImage } from '../../hooks/useProfileImage';
import ThemeToggle from '../ui/ThemeToggle';
import LanguageToggle from '../ui/LanguageToggle';
import SimpleNotificationCenter from '../dashboard/SimpleNotificationCenter';
import ErrorBoundary from '../ui/ErrorBoundary';

const DashboardHeader = ({ onMenuClick }) => {
  const { user, logout } = useAuth();
  const { isRTL } = useLanguage();
  const { getImageUrl, hasImage } = useProfileImage();

  // Utiliser les notifications seulement pour admin/staff
  const notificationsHook = useNotifications();
  const { unreadCount } = (user?.role === 'admin' || user?.role === 'staff' || user?.role === 'developer') ? notificationsHook : { unreadCount: 0 };

  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const userMenuRef = useRef(null);

  // Fermer le menu utilisateur quand on clique ailleurs
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setUserMenuOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = () => {
    logout();
    setUserMenuOpen(false);
  };

  const getRoleLabel = (role) => {
    switch (role) {
      case 'admin':
        return isRTL ? 'المدير' : 'Directeur';
      case 'staff':
        return isRTL ? 'موظف' : 'Personnel';
      case 'parent':
        return isRTL ? 'ولي أمر' : 'Parent';
      case 'developer':
        return 'Developer';
      default:
        return role;
    }
  };

  const getRoleBadgeColor = (role) => {
    switch (role) {
      case 'admin':
        return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200';
      case 'staff':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
      case 'parent':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case 'developer':
        return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
    }
  };

  // Obtenir le label du poste selon le genre
  const getPositionLabel = (position, gender) => {
    const positions = {
      director: { male: { fr: 'Directeur', ar: 'مدير' }, female: { fr: 'Directrice', ar: 'مديرة' } },
      educator: { male: { fr: 'Éducateur', ar: 'مربي' }, female: { fr: 'Éducatrice', ar: 'مربية' } },
      assistant_educator: { male: { fr: 'Assistant éducateur', ar: 'مساعد مربي' }, female: { fr: 'Assistante éducatrice', ar: 'مساعدة مربية' } },
      nurse: { male: { fr: 'Infirmier', ar: 'ممرض' }, female: { fr: 'Infirmière', ar: 'ممرضة' } },
      psychologist: { male: { fr: 'Psychologue', ar: 'أخصائي نفسي' }, female: { fr: 'Psychologue', ar: 'أخصائية نفسية' } },
      cook: { male: { fr: 'Cuisinier', ar: 'طباخ' }, female: { fr: 'Cuisinière', ar: 'طباخة' } },
      cleaning: { male: { fr: 'Agent d\'entretien', ar: 'عامل نظافة' }, female: { fr: 'Agente d\'entretien', ar: 'عاملة نظافة' } },
      security: { male: { fr: 'Agent de sécurité', ar: 'حارس أمن' }, female: { fr: 'Agente de sécurité', ar: 'حارسة أمن' } },
      receptionist: { male: { fr: 'Réceptionniste', ar: 'موظف استقبال' }, female: { fr: 'Réceptionniste', ar: 'موظفة استقبال' } },
      driver: { male: { fr: 'Chauffeur', ar: 'سائق' }, female: { fr: 'Chauffeuse', ar: 'سائقة' } },
      health: { male: { fr: 'Médecin conventionné', ar: 'طبيب متعاقد' }, female: { fr: 'Médecin conventionnée', ar: 'طبيبة متعاقدة' } },
      kitchen: { male: { fr: 'Personnel de cuisine', ar: 'موظف مطبخ' }, female: { fr: 'Personnel de cuisine', ar: 'موظفة مطبخ' } },
      other: { male: { fr: 'Autre', ar: 'آخر' }, female: { fr: 'Autre', ar: 'أخرى' } }
    };

    if (!position || !positions[position]) return null;
    const genderKey = gender === 'female' ? 'female' : 'male';
    return isRTL ? positions[position][genderKey].ar : positions[position][genderKey].fr;
  };

  return (
    <header className="bg-white dark:bg-gray-800 shadow-sm border-b border-gray-200 dark:border-gray-700">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Menu mobile */}
          <div className="flex items-center lg:hidden">
            <button
              onClick={onMenuClick}
              className="p-2 rounded-md text-gray-400 hover:text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-primary-500"
            >
              <Menu className="w-6 h-6" />
            </button>
          </div>

          {/* Logo/Titre pour desktop */}
          <div className="hidden lg:flex lg:items-center">
            <Link to="/dashboard" className="flex items-center">
              <h1 className="text-xl font-semibold text-gray-900 dark:text-white">
                {isRTL ? 'لوحة التحكم' : 'Dashboard'}
              </h1>
            </Link>
          </div>

          {/* Actions */}
          <div className="flex items-center space-x-2 sm:space-x-4 rtl:space-x-reverse">
            {/* Lien retour au site */}
            <Link
              to="/"
              className="hidden sm:flex items-center px-3 py-2 text-sm font-medium text-gray-600 dark:text-gray-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-md transition-colors"
              title={isRTL ? 'العودة إلى الموقع' : 'Retour au site'}
            >
              <Home className="w-4 h-4 mr-2 rtl:mr-0 rtl:ml-2" />
              <span className="hidden sm:inline">
                {isRTL ? 'الموقع' : 'Site'}
              </span>
            </Link>
            {/* Notifications - Visible seulement pour admin/staff - Masqué sur mobile ≤1024px */}
            {(user?.role === 'admin' || user?.role === 'staff' || user?.role === 'developer') && (
              <button
                onClick={() => setNotificationOpen(true)}
                className="hidden lg:block p-2 text-gray-400 hover:text-gray-500 dark:hover:text-gray-300 relative transition-colors"
              >
                <Bell className="w-6 h-6" />
                {/* Badge de notification */}
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                    {unreadCount > 99 ? '99+' : unreadCount}
                  </span>
                )}
              </button>
            )}

            {/* Toggles */}
            <ThemeToggle />
            <LanguageToggle />

            {/* Menu utilisateur */}
            <div className="relative" ref={userMenuRef}>
              <button
                onClick={() => setUserMenuOpen(!userMenuOpen)}
                className="flex items-center space-x-2 sm:space-x-3 rtl:space-x-reverse p-1.5 sm:p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
              >
                {/* Avatar optimisé pour mobile */}
                <div className="w-8 h-8 rounded-full overflow-hidden bg-primary-100 dark:bg-primary-900 flex items-center justify-center flex-shrink-0 ring-2 ring-white dark:ring-gray-800">
                  {hasImage() ? (
                    <img
                      src={getImageUrl()}
                      alt="Photo de profil"
                      className="w-full h-full object-cover"
                      crossOrigin="anonymous"
                      onError={(e) => {
                        console.error('❌ Erreur chargement image header:', e.target.src);
                        e.target.style.display = 'none';
                        e.target.nextElementSibling.style.display = 'flex';
                      }}
                    />
                  ) : null}
                  <div className={`w-full h-full flex items-center justify-center ${hasImage() ? 'hidden' : ''}`}>
                    <User className="w-4 h-4 sm:w-5 sm:h-5 text-primary-600 dark:text-primary-400" />
                  </div>
                </div>
                {/* Infos utilisateur - cachées sur très petits écrans */}
                <div className="hidden md:block text-left rtl:text-right min-w-0">
                  <div className="text-sm font-medium text-gray-900 dark:text-white truncate">
                    {user?.first_name} {user?.last_name}
                  </div>
                  <div className="flex items-center space-x-2 rtl:space-x-reverse">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${getRoleBadgeColor(user?.role)}`}>
                      {/* Afficher le poste si défini, sinon le rôle générique */}
                      {user?.staff_position && getPositionLabel(user.staff_position, user.gender)
                        ? getPositionLabel(user.staff_position, user.gender)
                        : getRoleLabel(user?.role)
                      }
                    </span>
                  </div>
                </div>
                <ChevronDown className="hidden sm:block w-4 h-4 text-gray-400 flex-shrink-0" />
              </button>

              {/* Dropdown menu */}
              {userMenuOpen && (
                <div className="absolute right-0 rtl:right-auto rtl:left-0 mt-2 w-56 bg-white dark:bg-gray-800 rounded-lg shadow-lg ring-1 ring-black ring-opacity-5 z-50">
                  <div className="py-1">
                    {/* Menu items */}
                    <Link
                      to="/profile"
                      onClick={() => setUserMenuOpen(false)}
                      className="flex items-center px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                    >
                      <User className="w-4 h-4 mr-3 rtl:mr-0 rtl:ml-3" />
                      {isRTL ? 'الملف الشخصي' : 'Profil'}
                    </Link>

                    {/* Paramètres - Admin, Staff et Developer */}
                    {(user?.role === 'admin' || user?.role === 'staff' || user?.role === 'developer') && (
                      <Link
                        to={(user?.role === 'admin' || user?.role === 'developer') ? '/dashboard/settings' : '/dashboard/staff-settings'}
                        onClick={() => setUserMenuOpen(false)}
                        className="flex items-center px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                      >
                        <Settings className="w-4 h-4 mr-3 rtl:mr-0 rtl:ml-3" />
                        {isRTL ? 'الإعدادات' : 'Paramètres'}
                      </Link>
                    )}

                    <div className="border-t border-gray-200 dark:border-gray-700">
                      <button
                        onClick={handleLogout}
                        className="flex items-center w-full px-4 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-gray-100 dark:hover:bg-gray-700"
                      >
                        <LogOut className="w-4 h-4 mr-3 rtl:mr-0 rtl:ml-3" />
                        {isRTL ? 'تسجيل الخروج' : 'Déconnexion'}
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Centre de notifications avec ErrorBoundary */}
      <ErrorBoundary
        fallbackMessage="Erreur lors du chargement des notifications"
        showRetry={true}
      >
        <SimpleNotificationCenter
          isOpen={notificationOpen}
          onClose={() => setNotificationOpen(false)}
        />
      </ErrorBoundary>
    </header>
  );
};

export default DashboardHeader;
